Hence $\kappa(x,x) = \kappa(y,y)$ for all unit vectors $x\in T_pM_1$ and $y\in T_qM_2$. 
Thus there exists a function $f \colon M_1\times M_2 \to \mathrm{I\!R}_+$  such that
$\kappa_1(x,x) = f(p,q) = \kappa_2(y,y)$ for all unit vectors $x$ and $y$, i.e. $\kappa =  f\langle\ ,\ \rangle$.  Inserting this into~\eqref{eq:Bianchis_cyclic_sum_is_parallel} implies that $(n + 2)\mathrm{d} f$ is parallel, hence
$\nabla \mathrm{d} f = 0$. Substituting this into~\eqref{eq:erste_vorstufe_zur_Bianchi_identity} yields
\begin{align*}
& \mathfrak{S}_{123}\, \mathrm{d}_{x_1}f \langle x_2,x_3 \rangle\;\;=\;\;3\,n\, \langle x_2,x_3\rangle \mathrm{d}_{x_1}f + (n-1) \mathfrak{S}_{23}\langle x_1,x_2 \rangle\, \mathrm{d}_{x_3}f.
\end{align*}
Evaluating this equation with $x_1 = x_2 = x_3$ implies that $(n - 1) \mathrm{d} f = 0$. Therefore if $n > 1$ then $\kappa$ is a constant multiple of the metric tensor. We conclude that $M$ is irreducible.
\end{proof}


\bigskip
\begin{corollary}\label{co:contracted_Bianchi_identity}
If $\dim(M) \geq  2$, then the contraction~\eqref{eq:divergenz_versus_differential_der_spur} of the Killing equation holds.
\end{corollary}
\begin{proof} 
We can assume that $\kappa$ is not a constant multiple of the metric tensor,
since otherwise~\eqref{eq:divergenz_versus_differential_der_spur} is obvious. Then, on
the one hand, $M$ is irreducible by the previous lemma and hence the holonomy
group acts fixed point free on tangent vectors,  because $\dim(M)\geq 2$. On
the other hand, since the contraction
of~\eqref{eq:Bianchis_cyclic_sum_is_parallel} implies that the 1-form
$\lambda\;:=\;\mathrm{d} \, \mathrm{tr} \, \kappa - 2 \delta \kappa$ is parallel, the latter is fixed under the holonomy group at each point. We conclude that $\lambda = 0$.
\end{proof}

