Let $R_1$ denote the algebraic curvature tensor defined by
\begin{equation}
R_1(x,y,z)\;:=\;- \langle x , z \rangle y + \langle y , z \rangle x
\end{equation}
for all $x,y,z\in T_pM$. If $g$ is positive definite, then this is the curvature tensor of a round
sphere of radius one.



Recall that the $1$-nullity of a pseudo Riemannian manifold is the subspace of $T_pM$ defined by
\begin{equation}\label{eq:curvature_constancy}
\mathcal{C}_1(T_pM)\;:=\;\{x\in T_pM| R(x,y,z)= R_1(x,y,z)\}.
\end{equation}
Hence a vector $x$ belongs to $\mathcal{C}_1(T_pM)$ if and only if the sectional curvature of any two-plane in $T_pM$ containing $x$ is equal to one (see~\cite{Gray1},~\cite{MoSe1}).
For example, a Sasakian vector field $\xi$ belongs at each point to the
$1$-nullity distribution. 

In general, $\mathcal{C}_1(TM)\;:=\;\bigcup_{p\in M}\mathcal{C}_1(T_pM)$ is not a subbundle of $TM$. However, for a symmetric space $\nabla R = 0$ implies that $\mathcal{C}_1(TM)$ is invariant under parallel translation and hence a parallel vector subbundle of $TM$.



\bigskip
\begin{lemma}\label{le:curvature_constancy}
If $\dim(M) \geq  2$, then the gradient of $\mathrm{tr} \, \kappa$ belongs to the 1-nullity $\mathcal{C}_1(TM)$ everywhere.
\end{lemma}
\begin{proof}
Let $f := \mathrm{tr} \, \kappa$. Since l.h.s. of~\eqref{eq:zweite_vorstufe_zur_Bianchi_identity} is completely
symmetric in $u_1,u_2,u_3$, the same is true for the right hand side of that
equation. Hence
\begin{align*}
& 3\, \big (\nabla^3_{y_1,y_2,y_3}f + 2\, \langle y_2,y_3\rangle \mathrm{d} f(y_1)
+ \mathfrak{S}_{23}\langle y_1,y_2\rangle \mathrm{d} f(y_3) \big )\\
&\;\;=\;\; \mathfrak{S}_{123} \big (\nabla^3_{y_1,y_2,y_3}f + 2\, \langle y_2,y_3\rangle \mathrm{d} f(y_1)
+ \mathfrak{S}_{23}\langle y_1,y_2\rangle  \mathrm{d} f(y_3) \big )\\
&\;\;=\;\;\mathfrak{S}_{123}\big (\nabla^3_{y_1,y_2,y_3}f +  4\,\langle y_1,y_2\rangle  \mathrm{d} f(y_3)\big )\\
&\;\;=\;\;\nabla^3_{y_1,y_2,y_3}f + \nabla^3_{y_3,y_1,y_2}f + \nabla^3_{y_2,y_3,y_1}f  + 4\,\mathfrak{S}_{123}\,\langle y_1,y_2\rangle \mathrm{d} f(y_3).
\end{align*}
Using the symmetry of the Hessian $\nabla\mathrm{d} f$, we have
\begin{align*}
 \nabla^3_{y_3,y_1,y_2}f &\;\;=\;\;\nabla^2_{y_1,y_3}\mathrm{d} f(y_2) + R_{y_3,y_1} \mathrm{d} f(y_2)\;\;=\;\;\nabla^3_{y_1,y_2,y_3}f + R_{y_3,y_1} \mathrm{d} f(y_2),\\
 \nabla^3_{y_2,y_3,y_1}f &\;\;=\;\; \nabla^3_{y_2,y_1,y_3}f\;\;=\;\;\nabla^2_{y_1,y_2,y_3}f + R_{y_2,y_1} \mathrm{d} f(y_3).
\end{align*}
Further,
\begin{equation*}
 6\, \langle y_2,y_3\rangle \mathrm{d} f(y_1)
+ 3\,\mathfrak{S}_{23}\langle y_1,y_2\rangle \mathrm{d} f(y_3) - 4\,\mathfrak{S}_{123}\,\langle y_1,y_2\rangle \mathrm{d} f(y_3)\;\;=\;\;2\, \langle y_2,y_3\rangle
\mathrm{d} f(y_1) - \mathfrak{S}_{23}\langle y_1,y_2\rangle \mathrm{d} f(y_3)
\end{equation*}

